export type Failure = 'offline' | 'timeout' | 'gateway' | 'server' | 'client'

export class ApiError extends Error {
  constructor(public kind: Failure, public status = 0) {
    super(`${kind} ${status}`)
  }
}

export async function apiGet<T>(path: string): Promise<T> {
  let res: Response
  try {
    // No answer within 10 seconds? Stop waiting. No endless spinner
    res = await fetch(path, { signal: AbortSignal.timeout(10_000) })
  } catch (e) {
    // No response at all: internet, DNS or TLS. Or the time limit ran out
    const timedOut = e instanceof DOMException && e.name === 'TimeoutError'
    throw new ApiError(timedOut ? 'timeout' : 'offline')
  }

  if ([502, 503, 504].includes(res.status)) {
    throw new ApiError('gateway', res.status) // someone in front of the app answered
  }
  if (res.status >= 500) throw new ApiError('server', res.status)
  if (!res.ok) throw new ApiError('client', res.status)

  return (await res.json()) as T // read the JSON only after checking the status
}

