final readonly class Cursor
{
    public function __construct(
        public DateTimeImmutable $createdAt,
        public int $id,
    ) {
    }

    public function encode(): string
    {
        $raw = $this->createdAt->format(DATE_ATOM).'|'.$this->id;

        return rtrim(strtr(base64_encode($raw), '+/', '-_'), '=');
    }

    public static function decode(string $token): self
    {
        $raw = base64_decode(strtr($token, '-_', '+/'), true);
        if (false === $raw || !str_contains($raw, '|')) {
            throw new BadRequestHttpException('Invalid cursor');
        }
        [$at, $id] = explode('|', $raw, 2);

        return new self(new DateTimeImmutable($at), (int) $id);
    }

    public static function fromOrder(Order $order): self
    {
        return new self($order->getCreatedAt(), $order->getId());
    }
}

public function page(?Cursor $after, int $limit): array
{
    $qb = $this->createQueryBuilder('o')
        ->orderBy('o.createdAt', 'DESC')
        ->addOrderBy('o.id', 'DESC')          // tie-breaker
        ->setMaxResults($limit + 1);          // one extra: is there more?

    if (null !== $after) {
        $qb->andWhere('o.createdAt < :at OR (o.createdAt = :at AND o.id < :id)')
            ->setParameter('at', $after->createdAt, Types::DATETIME_IMMUTABLE)
            ->setParameter('id', $after->id);
    }

    return $qb->getQuery()->getResult();
}

#[Route('/api/v1/orders', methods: ['GET'])]
public function list(
    OrderRepository $orders,
    #[MapQueryParameter] ?string $after = null,
    #[MapQueryParameter] int $limit = 20,
): JsonResponse {
    $limit = max(1, min($limit, 100));
    $rows = $orders->page($after ? Cursor::decode($after) : null, $limit);

    $hasMore = count($rows) > $limit;
    $rows = array_slice($rows, 0, $limit);

    return $this->json([
        'items' => array_map(OrderDto::from(...), $rows),
        'nextCursor' => $hasMore ? Cursor::fromOrder(end($rows))->encode() : null,
    ]);
}

