final class ApiProblemListener
{
    public function __invoke(ExceptionEvent $event): void
    {
        if (!str_starts_with($event->getRequest()->getPathInfo(), '/api/')) {
            return;
        }
        $e = $event->getThrowable();
        $violations = $e->getPrevious() instanceof ValidationFailedException
            ? $e->getPrevious()->getViolations() : null;

        [$status, $code] = match (true) {
            $e instanceof InsufficientStockException => [409, 'stock_insufficient'],
            null !== $violations => [422, 'validation_failed'],
            $e instanceof HttpExceptionInterface => [$e->getStatusCode(), 'http_error'],
            default => [500, 'internal_error'],
        };

        $body = [
            'type' => 'https://shop.example/problems/'.$code,
            'title' => Response::$statusTexts[$status],
            'status' => $status,
            'code' => $code,
            'detail' => $status < 500 ? $e->getMessage() : 'Something went wrong on the server',
        ];
        if (null !== $violations) {
            $body['errors'] = $this->errors($violations);
        }

        $event->setResponse(new JsonResponse($body, $status, [
            'Content-Type' => 'application/problem+json',
        ]));
    }
}

