private function errors(ConstraintViolationListInterface $violations): array
{
    $errors = [];
    foreach ($violations as $v) {
        $constraint = $v instanceof ConstraintViolation ? $v->getConstraint() : null;

        $errors[] = [
            'field' => $v->getPropertyPath(),
            'code' => $constraint?->payload['code'] ?? 'invalid',
            'message' => (string) $v->getMessage(),
        ];
    }

    return $errors;
}

const IDEMPOTENT = ['GET', 'HEAD', 'PUT', 'DELETE', 'OPTIONS']
const TRANSIENT = [408, 429, 502, 503, 504]

export function canRetry(
  method: string,
  status: number | null, // null = no response arrived
  hasIdempotencyKey: boolean,
): boolean {
  const safeToRepeat = IDEMPOTENT.includes(method) || hasIdempotencyKey
  if (!safeToRepeat) return false // POST: it might end up done twice

  if (status === null) return true
  return TRANSIENT.includes(status)
}

export async function pay(payment: Payment): Promise<PaymentResult> {
  const key = crypto.randomUUID() // once per user action, not per attempt

  for (let attempt = 0; attempt < 3; attempt++) {
    let status: number | null = null
    try {
      const res = await fetch('/api/v1/payments', {
        method: 'POST',
        headers: { 'Idempotency-Key': key, 'Content-Type': 'application/json' },
        body: JSON.stringify(payment),
      })
      if (res.ok) return await res.json()
      status = res.status
    } catch {
      // timeout or network error: status stays null
    }
    if (!canRetry('POST', status, true)) break
    await sleep(500 * 2 ** attempt) // wait longer after each failure
  }
  throw new Error('payment failed')
}

#[Route('/api/v1/payments', methods: ['POST'])]
public function create(
    Request $request,
    #[MapRequestPayload] PaymentRequest $dto,
): JsonResponse {
    $key = $request->headers->get('Idempotency-Key')
        ?? throw new BadRequestHttpException('Idempotency-Key header is required');

    $saved = $this->cache->get('idem_'.$key, function (ItemInterface $item) use ($dto) {
        $item->expiresAfter(86400);
        $payment = $this->payments->charge($dto);   // runs once per key

        return ['status' => 201, 'body' => ['id' => $payment->id]];
    });

    return $this->json($saved['body'], $saved['status']);
}

#[AsEventListener]
final readonly class ApiRateLimitListener
{
    public function __construct(private RateLimiterFactory $apiPerClientLimiter)
    {
    }

    public function __invoke(RequestEvent $event): void
    {
        $request = $event->getRequest();
        if (!$event->isMainRequest() || !str_starts_with($request->getPathInfo(), '/api/')) {
            return;
        }

        $key = $request->headers->get('X-Api-Key') ?? $request->getClientIp() ?? 'anonymous';
        $limit = $this->apiPerClientLimiter->create($key)->consume();

        if (!$limit->isAccepted()) {
            $wait = max(1, $limit->getRetryAfter()->getTimestamp() - time());

            throw new TooManyRequestsHttpException($wait, 'Too many requests');
        }
    }
}

// Use only for idempotent requests (GET, PUT, DELETE)
export async function fetchWithBackoff(
  url: string,
  init: RequestInit = {},
  maxRetries = 4,
): Promise<Response> {
  for (let attempt = 0; ; attempt++) {
    const res = await fetch(url, init)
    const retryable = res.status === 429 || res.status === 503
    if (!retryable || attempt >= maxRetries) return res

    const retryAfter = Number(res.headers.get('Retry-After'))
    const cap = Math.min(30_000, 2 ** attempt * 1000)
    const waitMs = retryAfter > 0 ? retryAfter * 1000 : Math.random() * cap

    await new Promise((resolve) => setTimeout(resolve, waitMs))
  }
}

