final readonly class PriceCalculator
{
    public function __construct(
        private ProductRepository $products,
        private DiscountPolicy $discounts,
    ) {
    }

    /** @param list<CartItem> $items only the product id and quantity */
    public function quote(array $items): Quote
    {
        $subtotal = 0;
        foreach ($items as $item) {
            $product = $this->products->find($item->productId)
                ?? throw new ProductNotFoundException($item->productId);

            $subtotal += $product->getPriceCents() * $item->quantity;
        }

        $discount = $this->discounts->forSubtotal($subtotal);

        return new Quote($subtotal, $discount, $subtotal - $discount);
    }
}

#[Route('/api/orders', methods: ['POST'])]
public function create(
    #[MapRequestPayload] CreateOrderRequest $input,
    PriceCalculator $calculator,
    EntityManagerInterface $em,
): JsonResponse {
    $quote = $calculator->quote($input->items);

    $order = Order::place($this->getUser(), $quote);
    $em->persist($order);
    $em->flush();

    return $this->json([
        'id' => $order->getId(),
        'subtotal' => $quote->subtotal,
        'discount' => $quote->discount,
        'total' => $quote->total,
    ], 201);
}

